class Solution {
public:
    long long lastInteger(long long n) {
        long long first = 1, step = 1;
        bool fromLeft = true;
        while (n > 1) {
            if (!fromLeft && n % 2 == 0) first += step;
            n = (n + 1) / 2;
            step *= 2;
            fromLeft = !fromLeft;
        }
        return first;
    }
};
